17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Comparator;
20	import java.util.Map;
21	import java.util.regex.Pattern;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Normalizes a submitted telephone to its canonical stored form in E.164: spaces, dashes
27	 * and brackets are stripped; a leading '+' and country code are kept when present,
28	 * otherwise the default country code '+61' is assumed and a single leading '0' is dropped
29	 * from the national digits. The result must carry 8 to 15 digits after the '+', and for a
30	 * recognised country code the national number (the digits after the country code) must be
31	 * exactly the length that country requires ('+61' => 9, '+1' => 10).
32	 */
33	@Component
34	public class TelephoneNormalizer {
35	
36	    /** Formatting characters removed before interpreting the number. */
37	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
38	
39	    /** Country code assumed when the submitted number carries no leading '+'. */
40	    private static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    /** The digits following the '+' must number between 8 and 15 inclusive. */
43	    private static final Pattern E164_DIGITS = Pattern.compile("[0-9]{8,15}");
44	
45	    /**
46	     * Required national-number length for each recognised country code. A country code absent
47	     * from this map carries no national-length constraint beyond the generic E.164 bounds.
48	     */
49	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
50	
51	    /**
52	     * @param telephone the raw submitted telephone (may be {@code null})
53	     * @return the telephone in E.164 form, i.e. a '+' followed by 8 to 15 digits
54	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
55	     */
56	    public String normalize(String telephone) {
57	        String cleaned = telephone == null ? "" : SEPARATORS.matcher(telephone.trim()).replaceAll("");
58	        String digits = cleaned.startsWith("+") ? cleaned.substring(1) : toDefaultCountry(cleaned);
59	        if (!E164_DIGITS.matcher(digits).matches() || !hasValidNationalLength(digits)) {
60	            throw new InvalidTelephoneException(telephone);
61	        }
62	        return "+" + digits;
63	    }
64	
65	    /**
66	     * Applies the default country code to national digits, dropping a single leading '0'.
67	     */
68	    private String toDefaultCountry(String national) {
69	        String trunkless = national.startsWith("0") ? national.substring(1) : national;
70	        return DEFAULT_COUNTRY_CODE + trunkless;
71	    }
72	
73	    /**
74	     * Checks the national number (the digits after the country code) against the length its
75	     * country code requires. The longest matching country code wins, so a '+61' number is
76	     * never mistaken for a shorter code. Country codes outside {@link #NATIONAL_NUMBER_LENGTHS}
77	     * carry no additional constraint.
78	     */
79	    private boolean hasValidNationalLength(String digits) {
80	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
81	            .filter(entry -> digits.startsWith(entry.getKey()))
82	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
83	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
84	            .orElse(true);
85	    }
86	}
